import base64
import pathlib
import tempfile

# pytester only ships test_*.py files, so the sample image is embedded and written out at runtime.
SAMPLE_HEIC_B64 = ""


def sample_image_path():
    path = pathlib.Path(tempfile.gettempdir()) / "tree-with-transparency.heic"
    path.write_bytes(base64.b64decode(SAMPLE_HEIC_B64))
    return path


def test_heif():
    import pi_heif

    sample = sample_image_path()
    assert pi_heif.is_supported(str(sample))
    heif_file = pi_heif.open_heif(str(sample), convert_hdr_to_8bit=False)
    assert heif_file.mode == "RGBA"


def test_pillow():
    from PIL import Image
    from pi_heif import register_heif_opener

    register_heif_opener()

    im = Image.open(sample_image_path())
    assert im.size == (262, 264)
    assert im.mode == "RGBA"
